1	import java.io.IOException;
2	import java.io.InputStream;
3	import java.io.PrintStream;
4	import java.io.UncheckedIOException;
5	import java.math.BigDecimal;
6	import java.util.ArrayList;
7	import java.util.List;
8	
9	import com.fasterxml.jackson.databind.JsonNode;
10	import com.fasterxml.jackson.databind.ObjectMapper;
11	import com.fasterxml.jackson.databind.node.ArrayNode;
12	import com.fasterxml.jackson.databind.node.ObjectNode;
13	
14	/**
15	 * Translates the JSON scenario protocol into MHPCO operations and back. The
16	 * protocol field names are binding; what the office does with a step, and what
17	 * it carries from one step to the next, is the {@link ClaimOffice}'s business.
18	 */
19	public class ClaimOfficeCli {
20	
21	    private static final ObjectMapper JSON = new ObjectMapper();
22	
23	    private static final int ACCEPTED = 0;
24	    private static final int REJECTED = 1;
25	
26	    /**
27	     * The claim-office executable: it reads one scenario from standard input,
28	     * answers on standard output, and exits with the status its report answers.
29	     */
30	    public static void main(String[] args) {
31	        System.exit(new ClaimOfficeCli().report(System.in, System.out, System.err));
32	    }
33	
34	    /**
35	     * Reports the scenario's results, answering the exit status the office
36	     * exits with: nothing but the results document on stdout when the office
37	     * accepts the scenario.
38	     */
39	    public int report(InputStream scenario, PrintStream results, PrintStream rejection) {
40	        try {
41	            results.print(resultsFor(scenario));
42	            return ACCEPTED;
43	        } catch (RejectedScenario refusal) {
44	            rejection.println(refusal.getMessage());
45	            return REJECTED;
46	        }
47	    }
48	
49	    private String resultsFor(InputStream scenario) {
50	        try {
51	            JsonNode input = JSON.readTree(scenario);
52	            ClaimOffice office =
53	                    new ClaimOffice(input.get("customer").get("yearsWithMHPCO").asInt());
54	            ObjectNode output = JSON.createObjectNode();
55	            ArrayNode resultsNode = output.putArray("results");
56	            JsonNode steps = input.get("steps");
57	            for (int stepIndex = 0; stepIndex < steps.size(); stepIndex++) {
58	                JsonNode step = steps.get(stepIndex);
59	                if ("claim".equals(step.get("op").asText())) {
60	                    writeSettlement(office.settleClaim(step.get("policy").asInt(), damages(step)),
61	                            resultsNode.addObject());
62	                    continue;
63	                }
64	                resultsNode.addObject().put("premium",
65	                        office.quote(stepIndex, insuredItems(step)));
66	            }
67	            return JSON.writeValueAsString(output);
68	        } catch (IOException e) {
69	            throw new UncheckedIOException(e);
70	        }
71	    }
72	
73	    private static void writeSettlement(ClaimOffice.Settlement settlement, ObjectNode result) {
74	        result.put("payout", settlement.payout().intValueExact());
75	        result.put("remainingCap", settlement.remainingCap().intValueExact());
76	    }
77	
78	    private static List<Damage> damages(JsonNode claimStep) {
79	        List<Damage> damages = new ArrayList<>();
80	        for (JsonNode damage : claimStep.get("incident").get("damages")) {
81	            damages.add(new Damage(damage.get("itemType").asText(),
82	                    new BigDecimal(damage.get("amount").asText())));
83	        }
84	        return damages;
85	    }
86	
87	    private static List<InsuredItem> insuredItems(JsonNode quoteStep) {
88	        List<InsuredItem> items = new ArrayList<>();
89	        for (JsonNode item : quoteStep.get("items")) {
90	            items.add(new InsuredItem(item.get("type").asText(),
91	                    item.path("cursed").asBoolean(false),
92	                    item.path("enchantment").asInt(0)));
93	        }
94	        return items;
95	    }
96	}
