1	import java.math.BigDecimal;
2	import java.util.HashMap;
3	import java.util.List;
4	import java.util.Map;
5	
6	/**
7	 * The office doing business with one customer over the course of a scenario: it
8	 * quotes premiums, writes the policies those quotes insure, and settles claims
9	 * against the policies it has written.
10	 *
11	 * What the office carries from one operation to the next is its own
12	 * bookkeeping, not the protocol's: how many contracts this customer already
13	 * holds (so the next quote knows it is a follow-up) and which policy each quote
14	 * wrote (so a later claim can be settled against it). A protocol revision
15	 * renaming a field changes none of it; deciding that some quote does not count
16	 * toward the customer's contracts would change it without touching a field
17	 * name.
18	 */
19	public class ClaimOffice {
20	
21	    private final PriceList priceList = new PriceList();
22	    private final PremiumPolicy premiumPolicy = new PremiumPolicy(priceList);
23	    private final ClaimPolicy claimPolicy = new ClaimPolicy();
24	
25	    private final int yearsWithMHPCO;
26	    private final Map<Integer, Policy> policiesByQuote = new HashMap<>();
27	    private int contractsAlreadyHeld;
28	
29	    public ClaimOffice(int yearsWithMHPCO) {
30	        this.yearsWithMHPCO = yearsWithMHPCO;
31	    }
32	
33	    /**
34	     * The office quotes a premium for the items brought and writes the policy
35	     * insuring them, filed under the quote it answers. Every quote the office
36	     * answers is another contract this customer holds, so the next one is a
37	     * follow-up.
38	     */
39	    public int quote(int quoteReference, List<InsuredItem> insuredItems) {
40	        Customer customer = new Customer(yearsWithMHPCO, contractsAlreadyHeld);
41	        policiesByQuote.put(quoteReference, Policy.covering(insuredItems, priceList));
42	        contractsAlreadyHeld++;
43	        return premiumPolicy.quote(customer, insuredItems);
44	    }
45	
46	    /**
47	     * The office settles a reported incident against the policy a previous
48	     * quote wrote, on that policy's own terms.
49	     */
50	    public Settlement settleClaim(int quoteReference, List<Damage> damages) {
51	        Policy policy = policiesByQuote.get(quoteReference);
52	        BigDecimal paid = policy.settle(damages, claimPolicy);
53	        return new Settlement(paid, policy.remainingCap());
54	    }
55	
56	    /** What one settled claim paid, and what the policy's cap has left afterwards. */
57	    public record Settlement(BigDecimal payout, BigDecimal remainingCap) {
58	    }
59	}
