1	import static java.util.stream.Collectors.counting;
2	import static java.util.stream.Collectors.groupingBy;
3	
4	import java.util.List;
5	import java.util.Map;
6	
7	/**
8	 * What a policy covers: the items the office recorded when it wrote the policy,
9	 * able to say which of them a reported damage is settled on.
10	 *
11	 * Reading a damage report against the covered items is a decision of its own,
12	 * revised on its own schedule and quite apart from what one damage earns or what
13	 * the cap allows.
14	 */
15	record Coverage(List<InsuredItem> insuredItems) {
16	
17	    static Coverage of(List<InsuredItem> insuredItems) {
18	        return new Coverage(List.copyOf(insuredItems));
19	    }
20	
21	    /**
22	     * What the office requires of an incident before it settles any of it: the
23	     * damages reported of a kind can be no more than the items of that kind the
24	     * policy covers, because each damage reported is a separate damage to a
25	     * separate covered item. An incident reporting more is no claim the office
26	     * will settle, and it refuses the claim whole rather than settling the part
27	     * it does cover.
28	     */
29	    void requireIncidentIsCovered(List<Damage> damages) {
30	        for (Map.Entry<String, Long> reported : countedByKind(damages).entrySet()) {
31	            if (reported.getValue() > coveredOfKind(reported.getKey())) {
32	                throw new RejectedScenario("the policy covers fewer items of type "
33	                        + reported.getKey() + " than the incident reports damaged");
34	            }
35	        }
36	    }
37	
38	    /**
39	     * How many damages the incident reports of each kind of item. The kind is
40	     * read from the damage report verbatim, as {@link #isOfKind} reads it of a
41	     * covered item, so that the two sides of the comparison count the same kinds.
42	     */
43	    private static Map<String, Long> countedByKind(List<Damage> damages) {
44	        return damages.stream().collect(groupingBy(Damage::itemType, counting()));
45	    }
46	
47	    /** How many items of the kind a damage report names the policy covers. */
48	    private long coveredOfKind(String damagedItemType) {
49	        return insuredItems.stream()
50	                .filter(insuredItem -> isOfKind(insuredItem, damagedItemType))
51	                .count();
52	    }
53	
54	    /**
55	     * The covered item whose terms a reported damage is settled on: the office
56	     * looks the reported kind of item up among the items it covers, and the
57	     * claim rules read the clauses from it. A damage naming a kind of item the
58	     * coverage does not include is no claim the office will settle.
59	     *
60	     * The office matches by the kind of item reported. Several covered items of
61	     * one kind are alike in everything the claim rules read, so which of them a
62	     * damage is settled on cannot change what it earns; what matters is that
63	     * there are enough of them, which
64	     * {@link #requireIncidentIsCovered} has already established.
65	     */
66	    InsuredItem itemDamagedBy(Damage damage) {
67	        for (InsuredItem insuredItem : insuredItems) {
68	            if (isOfKind(insuredItem, damage.itemType())) {
69	                return insuredItem;
70	            }
71	        }
72	        throw new RejectedScenario(
73	                "the policy does not cover an item of type " + damage.itemType());
74	    }
75	
76	    /**
77	     * Whether a covered item is of the kind a damage report names, which is all
78	     * the office asks of a covered item to settle a damage on it. Recognizing a
79	     * damage by something narrower than the kind reported would be a revision of
80	     * this one sentence.
81	     */
82	    private static boolean isOfKind(InsuredItem insuredItem, String damagedItemType) {
83	        return insuredItem.type().equals(damagedItemType);
84	    }
85	}
